# bash completion for dmcli — generated by `dmcli completion bash`.
# Regenerate after changing the CLI; it is derived from the argparse parser.
_dmcli() {
    local cur cmd i
    COMPREPLY=()
    cur="${COMP_WORDS[COMP_CWORD]}"
    local global="-h --help --db --json"
    cmd=""
    for ((i=1; i<COMP_CWORD; i++)); do
        case "${COMP_WORDS[i]}" in
            -*) ;;
            *) cmd="${COMP_WORDS[i]}"; break ;;
        esac
    done
    if [[ -z "$cmd" ]]; then
        COMPREPLY=( $(compgen -W "list info count graph stats group years tanks tags divers completion pull $global" -- "$cur") )
        return
    fi
    local opts=""
    case "$cmd" in
    list) opts="-h --help --year --period --from --to --tank --tanksize --exclude-tank --place --country --buddy --comment --tag --min-depth --max-depth --min-divetime --min-sac --max-sac --water --weekend --weekday --night --day --include-deleted --diver --all-divers --columns --desc" ;;
    info) opts="-h --help -t --temp --diver --all-divers --include-deleted" ;;
    count) opts="-h --help --year --period --from --to --tank --tanksize --exclude-tank --place --country --buddy --comment --tag --min-depth --max-depth --min-divetime --min-sac --max-sac --water --weekend --weekday --night --day --include-deleted --diver --all-divers" ;;
    graph) opts="-h --help --desc --year --period --from --to --tank --tanksize --exclude-tank --place --country --buddy --comment --tag --min-depth --max-depth --min-divetime --min-sac --max-sac --water --weekend --weekday --night --day --include-deleted --diver --all-divers airtemp avgdepth depth depthavg divetime maxdepth number o2 rmv sac tanksize temp time watertemp" ;;
    stats) opts="-h --help --year --period --from --to --tank --tanksize --exclude-tank --place --country --buddy --comment --tag --min-depth --max-depth --min-divetime --min-sac --max-sac --water --weekend --weekday --night --day --include-deleted --diver --all-divers" ;;
    group) opts="-h --help --limit --sort --year --period --from --to --tank --tanksize --exclude-tank --place --country --buddy --comment --tag --min-depth --max-depth --min-divetime --min-sac --max-sac --water --weekend --weekday --night --day --include-deleted --diver --all-divers Boat Buddy Computer Country Deco Divemaster Divesuit Divetype Entry O2 Place Rating Tanksize Tanktype UWCurrent Water Waves Weather year month weekend night buddy" ;;
    years) opts="-h --help --year --period --from --to --tank --tanksize --exclude-tank --place --country --buddy --comment --tag --min-depth --max-depth --min-divetime --min-sac --max-sac --water --weekend --weekday --night --day --include-deleted --diver --all-divers" ;;
    tanks) opts="-h --help" ;;
    tags) opts="-h --help --year --period --from --to --tank --tanksize --exclude-tank --place --country --buddy --comment --tag --min-depth --max-depth --min-divetime --min-sac --max-sac --water --weekend --weekday --night --day --include-deleted --diver --all-divers" ;;
    divers) opts="-h --help" ;;
    completion) opts="-h --help bash" ;;
    pull) opts="-h --help --key --folder --name --out" ;;
    esac
    COMPREPLY=( $(compgen -W "$opts $global" -- "$cur") )
}
complete -o default -F _dmcli dmcli
